entries[87226] = { ["name"] = "Banquet of the Grill", ["text"] = "Requires Level 90\nUse: Set out a Banquet of the Grill to feed up to 10 people in your raid or party!\n\nRestores 300000 health and ( 75000 / 5 * 20) mana over 20 sec. If you spend at least 10 seconds eating you will become well fed and gain 250 in a stat for 1 hour. May benefit some more than others.\nSell Price:" }
entries[87227] = { ["name"] = "Recipe: Banquet of the Grill", ["text"] = "Requires Cooking (600)\nUse: Teaches you how to prepare a Banquet of the Grill.\nSell Price:\nBanquet of the Grill\nRequires Level 90\nUse: Set out a Banquet of the Grill to feed up to 10 people in your raid or party!\n\nRestores 300000 health and ( 75000 / 5 * 20) mana over 20 sec. If you spend at least 10 seconds eating you will become well fed and gain 250 in a stat for 1 hour. May benefit some more than others.\nSell Price:\nRequires 100 Year Soy Sauce , Redbelly Mandarin (10), Raw Crab Meat (10), White Turnip (50)" }
entries[87228] = { ["name"] = "Great Banquet of the Grill", ["text"] = "Requires Level 90\nUse: Set out a Great Banquet of the Grill to feed up to 25 people in your raid or party!\n\nRestores 300000 health and ( 75000 / 5 * 20) mana over 20 sec. If you spend at least 10 seconds eating you will become well fed and gain 250 in a stat for 1 hour. May benefit some more than others.\nSell Price:" }
