entries[87250] = { ["name"] = "Depleted-Kyparium Rocket", ["text"] = "Unique\nMount\nRequires Level 20\nRequires Apprentice Riding\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nThe apex of goblin ingenuity! This mount changes depending on your Riding skill and location." }
entries[87251] = { ["name"] = "Geosynchronous World Spinner", ["text"] = "Unique\nMount\nRequires Level 20\nRequires Apprentice Riding\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nA device that rotates the very world beneath you! This mount changes depending on your Riding skill and location." }
entries[87252] = { ["name"] = "Steam-Filled Balloon", ["text"] = "\"Good luck!\"\nSell Price:" }
entries[87253] = { ["name"] = "Perpetual Leftovers", ["text"] = "Binds when picked up\nRequires Level 90\nUse: Set down some leftovers to feed your entire raid or party.\n\nRestores 300000 health and ( 75000 / 5 * 20) mana over 20 sec. (30 Min Cooldown)\nSell Price:" }
