entries[87267] = { ["name"] = "Codex of the Crusade", ["text"] = "Quest Item\nUnique\n\"The tome contains a complete account of the Scarlet Crusade's history. Also included are its statutes, bylaws, and rituals, as well as a complete roster of the organization's membership.\"" }
