entries[87276] = { ["name"] = "Glyph of Holy Resurrection", ["text"] = "Minor Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour resurrection target appears bathed in holy light for the duration of the Resurrection cast.\nSell Price:" }
