entries[87738] = { ["name"] = "Schematic: Lord Blastington's Scope of Doom", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make Lord Blastington's Scope of Doom.\n\nLord Blastington's Scope of Doom\nRequires Level 85\nUse: Permanently attaches Lord Blastington's special scope to a ranged weapon, sometimes increasing Agility by 1800 for 10 sec when dealing damage with ranged attacks.\n\nAttaching this scope to a ranged weapon causes it to become soulbound.\nSell Price:\nRequires Ghost Iron Bolts (18), Primordial Ruby (2), Spirit of Harmony" }
entries[87739] = { ["name"] = "Schematic: Mirror Scope", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make a Mirror Scope.\n\nMirror Scope\nRequires Level 85\nUse: Permanently attaches a mirrored scope to a ranged weapon, sometimes increases critical strike by 900 for 10 sec when dealing damage with ranged attacks.\n\nAttaching this scope to a ranged weapon causes it to become soulbound.\nSell Price:\nRequires Ghost Iron Bolts (4), Lapis Lazuli (2)" }
entries[87740] = { ["name"] = "Schematic: Lightweight Retinal Armor", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make Lightweight Retinal Armor.\n\nLightweight Retinal Armor\nBinds when picked up\nHead Cloth\n1733 Armor\n+1,522 Stamina\n+855 Intellect\n\nMeta Socket\nCogwheel Socket\nCogwheel Socket\nSocket Bonus: + 180 Intellect\n\nDurability 100 / 100\nRequires Level 87\nRequires Engineering (600)\nSell Price:\nRequires Living Steel (6), River's Heart , Ghost Iron Bolts (6)" }
entries[87741] = { ["name"] = "Schematic: Agile Retinal Armor", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make Agile Retinal Armor.\n\nAgile Retinal Armor\nBinds when picked up\nHead Leather\n2206 Armor\n+855 Agility\n+1,522 Stamina\n\nMeta Socket\nCogwheel Socket\nCogwheel Socket\nSocket Bonus: + 180 Agility\n\nDurability 100 / 100\nRequires Level 87\nRequires Engineering (600)\nSell Price:\nRequires Living Steel (6), Primal Diamond , Ghost Iron Bolts (6)" }
entries[87742] = { ["name"] = "Schematic: Camouflage Retinal Armor", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make Camouflage Retinal Armor.\n\nCamouflage Retinal Armor\nBinds when picked up\nHead Leather\n2206 Armor\n+1,522 Stamina\n+855 Intellect\n\nMeta Socket\nCogwheel Socket\nCogwheel Socket\nSocket Bonus: + 180 Intellect\n\nDurability 100 / 100\nRequires Level 87\nRequires Engineering (600)\nSell Price:\nRequires Living Steel (6), River's Heart , Ghost Iron Bolts (6)" }
entries[87743] = { ["name"] = "Schematic: Deadly Retinal Armor", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make Deadly Retinal Armor.\n\nDeadly Retinal Armor\nBinds when picked up\nHead Mail\n3069 Armor\n+855 Agility\n+1,522 Stamina\n\nMeta Socket\nCogwheel Socket\nCogwheel Socket\nSocket Bonus: + 180 Agility\n\nDurability 100 / 100\nRequires Level 87\nRequires Engineering (600)\nSell Price:\nRequires Living Steel (6), Wild Jade , Ghost Iron Bolts (6)" }
entries[87744] = { ["name"] = "Schematic: Energized Retinal Armor", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make Energized Retinal Armor.\n\nEnergized Retinal Armor\nBinds when picked up\nHead Mail\n3069 Armor\n+1,522 Stamina\n+855 Intellect\n\nMeta Socket\nCogwheel Socket\nCogwheel Socket\nSocket Bonus: + 180 Intellect\n\nDurability 100 / 100\nRequires Level 87\nRequires Engineering (600)\nSell Price:\nRequires Living Steel (6), River's Heart , Ghost Iron Bolts (6)" }
entries[87745] = { ["name"] = "Schematic: Specialized Retinal Armor", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make Specialized Retinal Armor.\n\nSpecialized Retinal Armor\nBinds when picked up\nHead Plate\n4191 Armor\n+1,522 Stamina\n+855 Intellect\n\nMeta Socket\nCogwheel Socket\nCogwheel Socket\nSocket Bonus: + 180 Intellect\n\nDurability 100 / 100\nRequires Level 87\nRequires Engineering (600)\nSell Price:\nRequires Living Steel (6), Sun's Radiance , Ghost Iron Bolts (6)" }
entries[87746] = { ["name"] = "Schematic: Reinforced Retinal Armor", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make Reinforced Retinal Armor.\n\nReinforced Retinal Armor\nBinds when picked up\nHead Plate\n4191 Armor\n+855 Strength\n+1,522 Stamina\n\nMeta Socket\nCogwheel Socket\nCogwheel Socket\nSocket Bonus: + 180 Strength\n\nDurability 100 / 100\nRequires Level 87\nRequires Engineering (600)\nSell Price:\nRequires Living Steel (6), Ghost Iron Bolts (12)" }
entries[87747] = { ["name"] = "Schematic: Locksmith's Powderkeg", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make a Locksmith's Powderkeg.\n\nLocksmith's Powderkeg\nRequires Engineering (525)\nUse: Blasts open locked doors and chests that require lockpicking skill of 450 and below.\nSell Price:\nRequires Simple Wood , High-Explosive Gunpowder" }
entries[87748] = { ["name"] = "Schematic: Watergliding Jets", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make Watergliding Jets.\nPermanently attaches waterjets to your belt, allowing you to walk on water and swim quickly for 12 sec.\n\nThe jets can only be activated every 30 sec and require 500 Engineering skill to use." }
entries[87750] = { ["name"] = "Schematic: G91 Landshark", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make a G91 Landshark.\n\nG91 Landshark\nRequires Level 85\nUse: Inflicts 37500 Fire damage to an enemy up to 45 yards away, as well as any enemies within 10 yards of the primary target. (1 Min Cooldown)\nRequires Ghost Iron Bolts (2), High-Explosive Gunpowder (2)" }
entries[87751] = { ["name"] = "Schematic: Goblin Flame Thrower, Mark II", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make a Goblin Flame Thrower, Mark II.\n\nGoblin Dragon Gun, Mark II\nRequires Level 85\nUse: Unleash a gout of lightning, dealing 4500 Nature damage to targets in a 10 yard cone in front of the caster every 0.5 sec for 4 sec.\n\nMay walk while casting. (30 Sec Cooldown)\n50 Charges\nSell Price:\nRequires Ghost Iron Bolts (3), High-Explosive Gunpowder (8)" }
entries[87752] = { ["name"] = "Schematic: Blingtron 4000", ["text"] = "Requires Engineering (600)\nUse: Teaches you how to make Blingtron 4000.\n\nBlingtron 4000\nBinds when picked up\nToy\nRequires Engineering (600)\nUse: Assembles the incredible Blingtron 4000, a robot of infinite wealth. Bling, as he likes to be called, will give out a random gift to anyone who talks to him, but only once per day. Lasts 10 min. (4 Hrs Cooldown)\nRequires Living Steel (4), Trillium Bar (4), Ghost Iron Bar (4), Vermilion Onyx (4), Wild Jade (4), Spirit of Harmony (4)" }
entries[87753] = { ["name"] = "Schematic: Mist-Piercing Goggles", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make Mist-Piercing Goggles.\n\nMist-Piercing Goggles\nBinds when equipped\nHead\nEquip: Allows you to see additional mining nodes and herbs while in Pandaria.\n\"While these goggles are very fashionable, they don't need to be worn to receive their special benefit.\"\nSell Price:\nRequires Ghost Iron Bolts (8), Spirit of Harmony (2)" }
entries[87754] = { ["name"] = "Schematic: Thermal Anvil", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make a Thermal Anvil.\n\nThermal Anvil\nUse: Places a Thermal Anvil at your feet, granting anyone nearby the use of both an anvil and a forge. Lasts 5 min. (5 Min Cooldown)\n20 Charges\nRequires High-Explosive Gunpowder (8), Ghost Iron Bolts (6)" }
entries[87755] = { ["name"] = "Schematic: Wormhole Generator: Pandaria", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make a Wormhole Generator: Pandaria.\n\nWormhole Generator: Pandaria\nBinds when used\nToy\nRequires Engineering (500)\nUse: Teleports you to somewhere in Pandaria. The exact location is difficult to predict, but will likely be far away. (15 Min Cooldown)\n\"There is a tiny note on the side: Wheeeeeeeeeee!\"\nSell Price:\nRequires Trillium Bar (12), Spirit of Harmony (2)" }
entries[87756] = { ["name"] = "Schematic: Steam-Filled Balloon", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make a Steam-Filled Balloon." }
entries[87757] = { ["name"] = "Schematic: Ghost Iron Dragonling", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make a Ghost Iron Dragonling.\n\nGhost Iron Dragonling\nBinds when equipped\nUnique-Equipped\nTrinket\nCogwheel Socket\nCogwheel Socket\nCogwheel Socket\n\nRequires Level 87\nEquip: Your attacks have a chance to summon a Ghost Iron Dragonling to fight with you for 20 sec. (Proc chance: 25%, 1m cooldown)\nSell Price:\nRequires Windwool Cloth (12), Ghost Iron Bolts (8), High-Explosive Gunpowder (4)" }
entries[87758] = { ["name"] = "Schematic: Mechanical Pandaren Dragonling", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make a Mechanical Pandaren Dragonling.\n\nMechanical Pandaren Dragonling\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss your whelpling.\nSell Price:\nRequires Ghost Iron Bar (4), Trillium Bar (6), Spirit of Harmony (2)" }
entries[87759] = { ["name"] = "Schematic: Big Game Hunter", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make a Big Game Hunter.\n\nBig Game Hunter\nBinds when equipped\nRanged Gun\n3,354 - 6,229 Damage Speed 2.80\n(1,711 damage per second)\n+449 Agility\n+703 Stamina\n+ 321 Critical Strike\n+ 283 Haste\n\nRed Socket\nSocket Bonus: + 10 Agility\n\nDurability 100 / 100\nRequires Level 85\nSell Price:\nRequires Ghost Iron Bolts (12), Hair Trigger , Walnut Stock , Mirror Scope" }
entries[87760] = { ["name"] = "Schematic: Long-Range Trillium Sniper", ["text"] = "Requires Engineering (525)\nUse: Teaches you how to make a Long-Range Trillium Sniper.\n\nLong-Range Trillium Sniper\nBinds when equipped\nRanged Gun\n5,704 - 10,595 Damage Speed 2.80\n(2,911 damage per second)\n+717 Agility\n+1,195 Stamina\n+ 435 Hit\n+ 546 Expertise\n\nYellow Socket\nSocket Bonus: + 10 Agility\n\nDurability 100 / 100\nRequires Level 90\nSell Price:\nRequires Trillium Bar (12), Hair Trigger , Spirit of Harmony , Lord Blastington's Scope of Doom" }
entries[87761] = { ["name"] = "Schematic: Depleted-Kyparium Rocket", ["text"] = "Requires Engineering (600)\nUse: Teaches you how to make a Depleted-Kyparium Rocket.\n\nDepleted-Kyparium Rocket\nUnique\nMount\nRequires Level 20\nRequires Apprentice Riding\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nThe apex of goblin ingenuity! This mount changes depending on your Riding skill and location.\nRequires Living Steel (12), Kyparite (200), Orb of Mystery (3), High-Explosive Gunpowder (12), Spirit of Harmony (12), Ghost Iron Bolts (20)" }
entries[87762] = { ["name"] = "Schematic: Geosynchronous World Spinner", ["text"] = "Requires Engineering (600)\nRequires Gnomish Engineer\nUse: Teaches you how to make a Geosynchronous World Spinner.\n\nGeosynchronous World Spinner\nUnique\nMount\nRequires Level 20\nRequires Apprentice Riding\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nA device that rotates the very world beneath you! This mount changes depending on your Riding skill and location.\nRequires Living Steel (12), Trillium Bar (12), Spirit of Harmony (12), Ghost Iron Bolts (20), Orb of Mystery (3)" }
entries[87763] = { ["name"] = "Ella's Brew", ["text"] = "Quest Item\nUse: Deliver a taste of Ella's Brew. (30 Sec Cooldown)\n\"A dark brew with a fragrant aroma. Deliver it to Chen Stormstout.\"" }
entries[87764] = { ["name"] = "Serpent's Heart Firework", ["text"] = "Use: Shoots a firework into the air that bursts into the form of the Jade Serpent.\nSell Price:" }
entries[87768] = { ["name"] = "Reins of the Onyx Cloud Serpent", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 90\nRequires Artisan Riding\nUse: Teaches you how to summon this mount. This is a flying mount. Requires Cloud Serpent Riding from the Order of the Cloud Serpent.\nSummons and dismisses a rideable Onyx Cloud Serpent. This is a flying mount. Requires Cloud Serpent Riding from the Order of the Cloud Serpent." }
