entries[87829] = { ["name"] = "Recipe: Incarnadine Ink", ["text"] = "Binds when picked up\nRequires Inscription (600)\nUse: Teaches you how to make Incarnadine Ink.\nSell Price:\nIncarnadine Ink\nBinds when picked up\nRequires Level 90\n\"A rare ink for calligraphy. It has no magical properties, but its hue is sought after by scribes for use in works on war.\"\nRequires Tigersblood Pigment (2), Spirit of Harmony , Starlight Ink" }
entries[87830] = { ["name"] = "Recipe: Tigersblood Tincture", ["text"] = "Binds when picked up\nRequires Inscription (600)\nUse: Teaches you how to make Tigersblood Tincture.\nSell Price:\nTigersblood Tincture\nBinds when picked up\nRequires Level 90\nUse: Stir very, very slowly to start the next stage of transformation.\n3 Charges\n\"It has the perfect hue to evoke violence and death. It requires much work, however, to be turned into usable ink.\"\nRequires Tigersblood Pigment (10)" }
