entries[87841] = { ["name"] = "Korven's Experimental Grenades", ["text"] = "Quest Item\nUse: Throw the vial, igniting Kyparite Plating on targets within 10 yards of the target location.\n\"Vials with two chambers containing reactive fluids. Handle with care.\"" }
