entries[87875] = { ["name"] = "Glyph of Lightspring", ["text"] = "Major Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Lightwell no longer automatically heals nearby targets, but can be clicked by players to deal 50% more healing than normal.\nSell Price:" }
entries[87878] = { ["name"] = "Enormous Kunchong Mandibles", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"The powerful jaws of Karanosh have reduced countless mushan beasts to pulp for her hatchlings.\"" }
entries[87880] = { ["name"] = "Glyph of Nimble Brew", ["text"] = "Major Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nClearing an effect with Nimble Brew heals you for 10% of your maximum health.\nSell Price:" }
entries[87881] = { ["name"] = "Glyph of Crackling Tiger Lightning", ["text"] = "Minor Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Crackling Jade Lightning visual is altered to the color of the White Tiger celestial.\nSell Price:" }
entries[87882] = { ["name"] = "Glyph of Flying Serpent Kick", ["text"] = "Minor Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Flying Serpent Kick automatically ends when you fly into an enemy, triggering the area of effect damage and snare.\nSell Price:" }
entries[87883] = { ["name"] = "Glyph of Honor", ["text"] = "Minor Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYou honorably bow after each successful Touch of Death.\nSell Price:" }
entries[87884] = { ["name"] = "Glyph of Jab", ["text"] = "Minor Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYou always will attack with hands and fist with Jab, even with non-fist weapons equipped.\nSell Price:" }
entries[87885] = { ["name"] = "Glyph of Rising Tiger Kick", ["text"] = "Minor Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Rising Sun Kick's visual is altered to the color of the White Tiger.\nSell Price:" }
entries[87887] = { ["name"] = "Glyph of Spirit Roll", ["text"] = "Minor Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYou can cast Roll or Chi Torpedo while dead as a spirit.\nSell Price:" }
entries[87888] = { ["name"] = "Glyph of Fighting Pose", ["text"] = "Minor Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour spirit now appears in a fighting pose when using Transcendence.\nSell Price:" }
entries[87889] = { ["name"] = "Glyph of Water Roll", ["text"] = "Minor Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYou can Roll or Chi Torpedo over water.\nSell Price:" }
entries[87890] = { ["name"] = "Glyph of Zen Flight", ["text"] = "Minor Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nTeaches you the spell Zen Flight. Zen Flight requires a Flight Master's License in order to be cast.\n\nZen Flight\nYou fly through the air at a quick speed on a meditative cloud.\nSell Price:" }
entries[87891] = { ["name"] = "Glyph of Afterlife", ["text"] = "Major Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nIncreases the chance to summon a Healing Sphere when you kill an enemy while gaining experience or honor to 100%.\nSell Price:" }
entries[87892] = { ["name"] = "Glyph of Fists of Fury", ["text"] = "Major Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhen channeling Fists of Fury, your parry chance is increased by 100%.\nSell Price:" }
entries[87893] = { ["name"] = "Glyph of Fortifying Brew", ["text"] = "Major Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Fortifying Brew reduces damage taken by an additional 5%, but increases your health by 10% rather than 20%.\nSell Price:" }
entries[87894] = { ["name"] = "Glyph of Leer of the Ox", ["text"] = "Major Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nTeaches you the spell Leer of the Ox.\n\nLeer of the Ox\nYour Ox Statue stirs hatred in the target, reducing their movement speed by 50% and causing them to attack your Black Ox Statue for 8 sec. The statue must be within 40 yards of the target.\n\nRequires Black Ox Statue to be active.\nSell Price:" }
entries[87895] = { ["name"] = "Glyph of Life Cocoon", ["text"] = "Major Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nLife Cocoon can now be cast while stunned.\nSell Price:" }
entries[87896] = { ["name"] = "Glyph of Fortuitous Spheres", ["text"] = "Major Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nFalling below 25% health will automatically summon a healing sphere near you at no cost. This effect cannot occur more often than once every 30 seconds. (30s cooldown)\nSell Price:" }
entries[87897] = { ["name"] = "Glyph of Paralysis", ["text"] = "Major Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Paralysis ability also removes all damage over time effects from the target.\nSell Price:" }
entries[87898] = { ["name"] = "Glyph of Sparring", ["text"] = "Classes: Monk\nRequires Level 25\nUse:\nSell Price:" }
entries[87899] = { ["name"] = "Glyph of Detox", ["text"] = "Major Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nDetox heals your target for 5% when it successfully removes a harmful effect.\nSell Price:" }
entries[87900] = { ["name"] = "Glyph of Touch of Karma", ["text"] = "Major Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Touch of Karma now has a 25 yard range.\nSell Price:" }
entries[87901] = { ["name"] = "Glyph of Targeted Expulsion", ["text"] = "Major Glyph\nClasses: Monk\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\n[ Mistweaver : Outside of Battlegrounds and Arenas:\nYour Uplift no longer costs Chi, but instead costs 10% Mana.\n\nInside of Battlegrounds and Arenas: ]Expel Harm can now be used on other allies, but the healing is reduced by 50% on them.\nSell Price:" }
